{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 버스 정류장에서 전자담배 흡연이 괜찮은지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제5조제1항제7호에 따라 시 관할 구역의 버스정류소는 금연구역으로 지정할 수 있는 장소에 해당한다. 같은 조례 제5조제4항은 누구든지 제1항에 따라 지정된 금연구역에서 흡연을 해서는 아니된다고 정하고 있다. 따라서 버스 정류장에서 전자담배를 피우는 것은 허용되지 않는다.",
          "b_ids": "금연:제5조제1항제7호, 금연:제5조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
